const InfoCard = ({
  label,
  value,
}: {
  label: string;
  value: string | number;
}) => (
  <div className="rounded-lg border border-white/10 bg-black/30 p-4">
    <p className="mb-1 text-[11px] uppercase tracking-wider text-gray-500">
      {label}
    </p>

    <p className="truncate text-sm font-medium text-white">{value || "-"}</p>
  </div>
);

